CREATE INDEX IF NOT EXISTS idx_rank2_all ON players (total_stars DESC, best_score DESC, total_left DESC, up_all ASC, id ASC) WHERE hidden = 0 AND total_stars > 0; CREATE INDEX IF NOT EXISTS idx_rank2_easy ON players (stars_easy DESC, best_score DESC, left_easy DESC, up_easy ASC, id ASC) WHERE hidden = 0 AND stars_easy > 0; CREATE INDEX IF NOT EXISTS idx_rank2_normal ON players (stars_normal DESC, best_score DESC, left_normal DESC, up_normal ASC, id ASC) WHERE hidden = 0 AND stars_normal > 0; CREATE INDEX IF NOT EXISTS idx_rank2_hard ON players (stars_hard DESC, best_score DESC, left_hard DESC, up_hard ASC, id ASC) WHERE hidden = 0 AND stars_hard > 0;
